    openRepo(dir);
    defer closeRepo();
    defer clearCommandError();

    gitDo(&.{ "merge", "--no-edit", "other" });
    try std.testing.expectEqual(git.State.merge, history.?.state);

    const cmd = history.?.state.command() orelse return error.NoCommandForState;
    gitDo(&.{ cmd, "--abort" });
